import{_ as t,o as a,c as r,a5 as o}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"3.4.9 Remove Member","description":"","frontmatter":{},"headers":[],"relativePath":"feature/agency-workspace/3-4-9-remove-member/spec.md","filePath":"feature/agency-workspace/3-4-9-remove-member/spec.md"}'),n={name:"feature/agency-workspace/3-4-9-remove-member/spec.md"};function s(i,e,l,c,h,d){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="_3-4-9-remove-member" tabindex="-1">3.4.9 Remove Member <a class="header-anchor" href="#_3-4-9-remove-member" aria-label="Permalink to &quot;3.4.9 Remove Member&quot;">​</a></h1><h2 id="function-trigger" tabindex="-1">Function Trigger <a class="header-anchor" href="#function-trigger" aria-label="Permalink to &quot;Function Trigger&quot;">​</a></h2><p>The Owner of an Agency opens the Member list of that Agency (<code>/agencies/:agencyId/members</code>), selects Remove on a member row and confirms.</p><h2 id="function-description" tabindex="-1">Function Description <a class="header-anchor" href="#function-description" aria-label="Permalink to &quot;Function Description&quot;">​</a></h2><ul><li><strong>Actors / Roles:</strong> Agency Owner.</li><li><strong>Purpose:</strong> Let the Owner take a member out of the Agency so that person loses access, while everything they produced while working there stays with the Agency as shared property.</li><li><strong>Interface:</strong> Member list page (<code>/agencies/:agencyId/members</code>) with a Remove action on each member row and a confirmation step.</li><li><strong>Data Processing:</strong> The system loads the Agency, confirms the caller is its Owner, locates the member record inside that Agency, refuses the removal when the record is the Owner, and otherwise removes the member record. Removing the record ends the person&#39;s access to every Workspace of the Agency at once, while the resources they created remain in place, owned by the Agency as before.</li></ul><h2 id="screen-layout" tabindex="-1">Screen Layout <a class="header-anchor" href="#screen-layout" aria-label="Permalink to &quot;Screen Layout&quot;">​</a></h2><p>Figure — Member list:</p><ul><li>One row per member with their name, email and member role.</li><li>A Remove action on each row behind a confirmation step, not offered for the Owner row.</li><li>On success the row disappears and the list refreshes.</li></ul><h2 id="function-details" tabindex="-1">Function Details <a class="header-anchor" href="#function-details" aria-label="Permalink to &quot;Function Details&quot;">​</a></h2><h3 id="data-specifications" tabindex="-1">Data Specifications <a class="header-anchor" href="#data-specifications" aria-label="Permalink to &quot;Data Specifications&quot;">​</a></h3><ul><li><strong>Input required:</strong> The Agency identifier (<code>agencyId</code>), the member record identifier (<code>memberId</code>) and a signed-in session as the Agency Owner.</li><li><strong>Input optional:</strong> None.</li><li><strong>System data:</strong> The Agency record and its Owner identifier (access check), and the member record with its Agency and its role.</li><li><strong>Output:</strong> No data is returned. The member record is removed and the person loses access to the Agency and to all of its Workspaces.</li></ul><h3 id="business-rules" tabindex="-1">Business Rules <a class="header-anchor" href="#business-rules" aria-label="Permalink to &quot;Business Rules&quot;">​</a></h3><ul><li><strong>BR-28:</strong> Remove member: only Owner/Manager-equivalent (here, the Agency Owner) may remove; the last remaining OWNER cannot be removed. Anybody other than the Owner is refused with <code>403 NOT_AGENCY_OWNER</code>.</li><li>The identifier used is the member record of the Agency, not the person&#39;s user identifier. A record that does not exist, or belongs to another Agency, is refused with <code>404 NOT_FOUND</code>.</li><li>The Owner&#39;s own member record can never be removed, whatever the caller attempts (BR-28, &quot;the last remaining OWNER cannot be removed&quot;). The attempt is refused with <code>409 CANNOT_REMOVE_OWNER</code>. There is no ownership transfer, so the Owner cannot hand the Agency over before stepping away.</li><li>Removing a member ends their access to every Workspace of the Agency at once, including Workspaces where they held a manager or member role, because access everywhere rests on the member record that has just been removed.</li><li>The resources the removed member created — tasks, materials, content and the like — are not removed and do not change owner. They stay with the Workspace and the Agency as shared property.</li><li>When the person is invited back into the Agency later, they can edit and continue using the resources they created before, because that work never stopped belonging to the Agency.</li><li>Work assigned to the removed member is not reassigned automatically. A manager has to handle it by hand.</li></ul><h3 id="validation" tabindex="-1">Validation <a class="header-anchor" href="#validation" aria-label="Permalink to &quot;Validation&quot;">​</a></h3><ul><li>Caller is not the Agency Owner → Display: MSG39</li><li>The member record does not exist, or belongs to another Agency → Display: MSG38</li><li>The member record is the Owner&#39;s own → Display: MSG37, and nothing is removed.</li></ul><h2 id="functionalities" tabindex="-1">Functionalities <a class="header-anchor" href="#functionalities" aria-label="Permalink to &quot;Functionalities&quot;">​</a></h2><h3 id="normal-flow" tabindex="-1">Normal Flow <a class="header-anchor" href="#normal-flow" aria-label="Permalink to &quot;Normal Flow&quot;">​</a></h3><ol><li>The Owner opens the Member list of an Agency.</li><li>The Owner selects Remove on a member row other than their own and confirms.</li><li>The client submits the removal with the member record identifier.</li><li>The system loads the Agency and confirms the caller is its Owner.</li><li>The system locates the member record inside that Agency.</li><li>The system removes the member record.</li><li>The client drops the row and shows a confirmation; toast MSG36. The person loses access to the Agency and to every one of its Workspaces immediately.</li><li>The resources that person created stay in the Workspace and the Agency, unchanged and still usable.</li></ol><h3 id="abnormal-cases" tabindex="-1">Abnormal Cases <a class="header-anchor" href="#abnormal-cases" aria-label="Permalink to &quot;Abnormal Cases&quot;">​</a></h3><ul><li>4.a1: Caller is not the Agency Owner (BR-28) → <code>403 NOT_AGENCY_OWNER</code>, toast MSG39; nothing is removed. 4.a2: The caller returns to the Agency list and opens an Agency they own.</li><li>5.a1: The member record does not exist, or belongs to another Agency → <code>404 NOT_FOUND</code>, toast MSG38. 5.a2: The Owner refreshes the Member list.</li><li>5.b1: Remove selected on the Owner&#39;s own row (BR-28) → <code>409 CANNOT_REMOVE_OWNER</code>, toast MSG37; nothing is removed. 5.b2: The Owner accepts that self-removal is not available and, if stepping away, contacts support since there is no ownership transfer.</li><li>6.a1: The removed member had work in progress assigned to them in a Workspace → the work is not unassigned automatically; no error, no toast. 6.a2: A manager handles the reassignment by hand, because that work still belongs to the Workspace.</li></ul><h2 id="post-conditions" tabindex="-1">Post-Conditions <a class="header-anchor" href="#post-conditions" aria-label="Permalink to &quot;Post-Conditions&quot;">​</a></h2><ul><li>The member record no longer exists, and the person loses access to the Agency and to all of its Workspaces immediately.</li><li>The resources the person created remain with the Workspace and the Agency, and stay usable by anyone holding access.</li><li>Work assigned to the person remains assigned until a manager handles it.</li></ul>',22)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
